--
-- Name: enforce_single_basic_designation(); Type: FUNCTION; Schema: public; Owner: fusion_admin
--

CREATE FUNCTION public.enforce_single_basic_designation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
                    BEGIN
                        IF NEW.designation_id IS NOT NULL AND (
                        SELECT basic 
                        FROM globals_designation 
                        WHERE id = NEW.designation_id
                    ) = TRUE THEN
                        IF (
                            SELECT COUNT(*) 
                            FROM globals_holdsdesignation h 
                            JOIN globals_designation d 
                            ON h.designation_id = d.id
                            WHERE h.user_id = NEW.user_id AND d.basic = TRUE
                    ) > 0 THEN
                            RAISE EXCEPTION 'A user can only have one basic designation.';
                        END IF;
                    END IF;

                    RETURN NEW;
                END;
                $$;


ALTER FUNCTION public.enforce_single_basic_designation() OWNER TO fusion_admin;

